using MediatR;using ProjectNet.Application.Abstractions;using ProjectNet.Application.DTOs;namespace ProjectNet.Application.Queries.GetAllCustomers;public sealed class GetAllCustomersQueryHandler : IRequestHandler<GetAllCustomersQuery, IReadOnlyList<CustomerDto>> { private readonly ICustomerRepository _r; public GetAllCustomersQueryHandler(ICustomerRepository r)=>_r=r; public async Task<IReadOnlyList<CustomerDto>> Handle(GetAllCustomersQuery request, CancellationToken ct){ var customers=await _r.GetAllAsync(ct); return customers.Select(c=>c.ToDto()).ToList(); } }
